// Simplified Raft core — both sides of the two RPCs plus the commit rule.
// Illustrative: no timers, persistence, snapshots, or membership changes.
class RaftNode {
  constructor(id, peerIds) {
    this.id = id;
    this.peerIds = peerIds;          // ids of the OTHER nodes
    // Persistent state (must be fsync'd before answering any RPC):
    this.currentTerm = 0;
    this.votedFor = null;
    this.log = [];                   // [{ term, command }], index 0 = first entry
    // Volatile state:
    this.state = 'follower';
    this.commitIndex = -1;
    this.nextIndex = {};             // leader only: next entry to send each peer
    this.matchIndex = {};            // leader only: highest entry known replicated
  }
  lastIndex() { return this.log.length - 1; }
  lastTerm() { return this.log.length ? this.log[this.log.length - 1].term : 0; }
  majority() { return Math.floor((this.peerIds.length + 1) / 2) + 1; }
  observeTerm(term) {               // any RPC with a newer term => step down
    if (term > this.currentTerm) { this.currentTerm = term; this.votedFor = null; this.state = 'follower'; }
  }

  // ── RequestVote receiver: one vote per term + the ELECTION RESTRICTION ──
  handleRequestVote({ term, candidateId, lastLogIndex, lastLogTerm }) {
    this.observeTerm(term);
    const upToDate = lastLogTerm > this.lastTerm() ||
      (lastLogTerm === this.lastTerm() && lastLogIndex >= this.lastIndex());
    const grant = term === this.currentTerm && upToDate &&
      (this.votedFor === null || this.votedFor === candidateId);
    if (grant) this.votedFor = candidateId;
    return { term: this.currentTerm, voteGranted: grant };
  }

  // ── AppendEntries receiver: LOG MATCHING check, truncate conflicts, append ──
  handleAppendEntries({ term, prevLogIndex, prevLogTerm, entries, leaderCommit }) {
    this.observeTerm(term);
    if (term < this.currentTerm) return { term: this.currentTerm, success: false };
    this.state = 'follower';         // a current leader exists
    if (prevLogIndex >= 0 && this.log[prevLogIndex]?.term !== prevLogTerm) {
      return { term: this.currentTerm, success: false }; // gap or mismatch: leader backs up
    }
    entries.forEach((e, i) => {
      const idx = prevLogIndex + 1 + i;
      if (this.log[idx] && this.log[idx].term !== e.term) this.log.length = idx; // drop conflict + tail
      if (!this.log[idx]) this.log[idx] = e;
    });
    if (leaderCommit > this.commitIndex) {
      this.commitIndex = Math.min(leaderCommit, prevLogIndex + entries.length);
    }
    return { term: this.currentTerm, success: true };
  }

  // ── Candidate side ──
  startElection(cluster) {
    this.state = 'candidate'; this.currentTerm++; this.votedFor = this.id;
    let votes = 1;
    for (const p of this.peerIds) {
      const r = cluster[p].handleRequestVote({ term: this.currentTerm, candidateId: this.id,
        lastLogIndex: this.lastIndex(), lastLogTerm: this.lastTerm() });
      this.observeTerm(r.term);
      if (this.state !== 'candidate') return false;
      if (r.voteGranted) votes++;
    }
    if (votes < this.majority()) return false;
    this.state = 'leader';
    for (const p of this.peerIds) { this.nextIndex[p] = this.log.length; this.matchIndex[p] = -1; }
    this.log.push({ term: this.currentTerm, command: 'no-op' }); // lets old entries commit
    return true;
  }

  // ── Leader side: replicate, back up on rejection, then advance commitIndex ──
  replicate(cluster, reachable = this.peerIds) {
    for (const p of reachable) {
      for (;;) {
        const prev = this.nextIndex[p] - 1;
        const r = cluster[p].handleAppendEntries({ term: this.currentTerm, leaderId: this.id,
          prevLogIndex: prev, prevLogTerm: prev >= 0 ? this.log[prev].term : 0,
          entries: this.log.slice(prev + 1), leaderCommit: this.commitIndex });
        this.observeTerm(r.term);
        if (this.state !== 'leader') return;
        if (r.success) { this.matchIndex[p] = this.lastIndex(); this.nextIndex[p] = this.log.length; break; }
        this.nextIndex[p]--;                       // walk back until logs match
      }
    }
    // COMMIT RULE: highest N replicated on a majority AND log[N].term === currentTerm.
    // Older-term entries are never committed by counting replicas (Raft Figure 8);
    // they become committed implicitly when a current-term entry above them commits.
    for (let n = this.lastIndex(); n > this.commitIndex; n--) {
      const copies = 1 + this.peerIds.filter((p) => this.matchIndex[p] >= n).length;
      if (copies >= this.majority() && this.log[n].term === this.currentTerm) { this.commitIndex = n; break; }
    }
  }

  propose(command, cluster, reachable) {
    if (this.state !== 'leader') throw new Error('not leader — redirect client');
    this.log.push({ term: this.currentTerm, command });
    this.replicate(cluster, reachable);
    return this.commitIndex >= this.lastIndex(); // true => safe to answer the client
  }
}

// ── Demo: 3 nodes, a write that only reaches a minority, then leader change ──
const ids = ['A', 'B', 'C'];
const cluster = Object.fromEntries(ids.map((id) => [id, new RaftNode(id, ids.filter((x) => x !== id))]));
const { A, B, C } = cluster;

console.log(A.startElection(cluster), A.currentTerm);  // true 1
console.log(A.propose('SET x=1', cluster));             // true  (on a majority: committed)
console.log(A.propose('SET x=2', cluster, []));         // false (A is partitioned: uncommitted)

// The partition heals and B, which timed out, campaigns. A refuses to vote (A's log is longer, same last term),
// but C grants, and 2 of 3 votes is a majority.
console.log(B.startElection(cluster), B.currentTerm);  // true 2
B.replicate(cluster);   // A's uncommitted 'SET x=2' conflicts with B's log and is overwritten
B.replicate(cluster);   // next heartbeat carries the new commitIndex to followers
console.log(A.log.map((e) => `${e.term}:${e.command}`).join(' | '));
// 1:no-op | 1:SET x=1 | 2:no-op
console.log(A.commitIndex, B.commitIndex, C.commitIndex); // 2 2 2

// Classic Paxos — single-value consensus (illustrative)
// Models proposer and acceptor logic

class Acceptor {
  constructor() {
    this.promisedBallot = -1;  // highest ballot promised
    this.acceptedBallot = -1;  // ballot of last accepted proposal
    this.acceptedValue  = null;
  }

  // Phase 1: respond to Prepare(n)
  prepare(n) {
    if (n > this.promisedBallot) {
      this.promisedBallot = n;
      return {
        ok: true,
        acceptedBallot: this.acceptedBallot,
        acceptedValue:  this.acceptedValue
      };
    }
    return { ok: false }; // already promised higher ballot
  }

  // Phase 2: respond to Accept(n, v)
  accept(n, v) {
    if (n >= this.promisedBallot) {
      this.promisedBallot = n;
      this.acceptedBallot = n;
      this.acceptedValue  = v;
      return { ok: true };
    }
    return { ok: false }; // promised a higher ballot in the meantime
  }
}

class Proposer {
  constructor(id, acceptors) {
    this.id        = id;
    this.acceptors = acceptors;
    this.ballot    = id * 1000; // globally unique starting point
  }

  // `reachable` simulates a partition: only those acceptors get our messages
  async propose(myValue, reachable = this.acceptors, phase2Reach = reachable) {
    this.ballot++;
    const n = this.ballot;
    const majority = Math.floor(this.acceptors.length / 2) + 1;

    // --- Phase 1: Prepare ---
    const promises = await Promise.all(
      reachable.map(a => Promise.resolve(a.prepare(n)))
    );
    const granted = promises.filter(p => p.ok);
    if (granted.length < majority) throw new Error('Phase 1 failed — try higher ballot');

    // Adopt highest previously accepted value (Paxos safety rule)
    const alreadyAccepted = granted.filter(p => p.acceptedValue !== null);
    let valueToPropose = myValue;
    if (alreadyAccepted.length > 0) {
      // Must use the value with the highest accepted ballot
      const highest = alreadyAccepted.reduce((best, p) =>
        p.acceptedBallot > best.acceptedBallot ? p : best
      );
      valueToPropose = highest.acceptedValue;
      console.log(`Adopting prior value: ${valueToPropose} (ballot ${highest.acceptedBallot})`);
    }

    // --- Phase 2: Accept ---
    const accepts = await Promise.all(
      phase2Reach.map(a => Promise.resolve(a.accept(n, valueToPropose)))
    );
    const accepted = accepts.filter(a => a.ok);
    if (accepted.length < majority) throw new Error('Phase 2 failed — concurrent proposer?');

    console.log(`Consensus reached: value = ${valueToPropose}`);
    return valueToPropose;
  }
}

// Demo: p1 gets 'A' chosen, then crashes before telling anyone; p2 must not overwrite it
async function demo() {
  const acceptors = [new Acceptor(), new Acceptor(), new Acceptor()];
  const [a1, a2, a3] = acceptors;
  const p1 = new Proposer(1, acceptors); // ballots 1001, 1002, ...
  const p2 = new Proposer(2, acceptors); // ballots 2001, 2002, ...

  // p1 completes Phase 1 on everyone, but its Accept reaches only a1 and a2.
  // A majority (2 of 3) accepted 'A' at ballot 1001, so 'A' is CHOSEN.
  await p1.propose('A', acceptors, [a1, a2]);

  // p2 never heard from p1 and wants 'B'. Its Phase 1 reaches only a2 and a3 —
  // still a majority, and it must overlap the majority that accepted 'A' (at a2).
  const result = await p2.propose('B', [a2, a3]); // logs: Adopting prior value: A (ballot 1001)
  console.log('Final:', result);                  // Final: A — the chosen value survives
}
demo().catch((e) => console.error(e.message));
